window.RP_SESSION={"id":"S-8498acf727cd","messages":[{"id":"RP-0112007","time":"2026-04-14T08:16:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"스트레칭을 쭉하고선, 마리우스는 탁상 옆에 놓여진 티를 마셨다. 오래간만에 기숙사에서 자는 잠이었다.\n\n씻고, 옷을 갈아입고. 조금은 익숙해진 제 살별을 들었다. \n\n과연 어제 그것이 거짓말을 하지 않았을까라고 물어본다면, 당연히 아마도 그럴 것이다라는 답이 나올테지만. 작은 가능성마저 놓치고 싶지는 않았다.","characters":["P-b6d81d634c6e"]},{"id":"RP-0112008","time":"2026-04-14T08:16:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-0112009","time":"2026-04-14T09:17:00+09:00","room":"RP","name":"Maria Anaïs Ésther","profile":"Maria Anaïs Ésther","identity":"unresolved","type":"dialogue","body":"'마리우스'의 힘 판정 :\n[4] + [2] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.\n메시지가 삭제되었습니다.","characters":[]},{"id":"RP-0112010","time":"2026-04-14T11:33:00+09:00","room":"RP","name":"GM","profile":"GM","identity":"unresolved","type":"dialogue","body":"?","characters":[]},{"id":"RP-0112011","time":"2026-04-14T11:36:00+09:00","room":"RP","name":"Seon \"South Foot\"","profile":"Seon \"South Foot\"","identity":"unresolved","type":"dialogue","body":"물음표.","characters":[]}]};
